namespace StudentAttendanceSystemVS2012
{
 sealed class MainForm:Form
 {
  readonly Database db;readonly int userId;readonly int? teacherId;readonly string role,username,fullName;readonly Panel menu=new Panel{Dock=DockStyle.Fill,BackColor=Ui.Primary,AutoScroll=true},host=new Panel{Dock=DockStyle.Fill,BackColor=Ui.Background,Padding=new Padding(24,20,24,24)};readonly Label pageTitle=new Label{AutoSize=true,Font=new Font("Segoe UI Semibold",18),ForeColor=Ui.Text,Location=new Point(26,15)};readonly System.Collections.Generic.List<Button> buttons=new System.Collections.Generic.List<Button>();
  public MainForm(Database database,int id,int? teacher,string loginName,string name,string userRole){db=database;userId=id;teacherId=teacher;username=loginName;fullName=name;role=userRole;Text=(role=="Admin"?"Admin":"Lecturer")+" Dashboard - "+name;WindowState=FormWindowState.Maximized;MinimumSize=new Size(1000,650);Font=new Font("Segoe UI",10);BackColor=Ui.Background;BuildShell();Add("Overview",new OverviewPage(db,teacherId,name,role));if(role=="Admin")AddAdmin();else AddTeacher();Ui.Style(this);}
  void BuildShell(){var navigation=new Panel{Dock=DockStyle.Left,Width=230,BackColor=Ui.Primary};var brand=new Panel{Dock=DockStyle.Fill,BackColor=Ui.Primary};brand.Controls.Add(new Label{Text="●",ForeColor=Ui.Accent,Font=new Font("Segoe UI Semibold",17),AutoSize=true,Location=new Point(19,24)});brand.Controls.Add(new Label{Text="UCSPyay",ForeColor=Color.White,Font=new Font("Segoe UI Semibold",20),AutoSize=true,Location=new Point(48,20)});brand.Controls.Add(new Label{Text="UNIVERSITY ATTENDANCE PORTAL",ForeColor=Color.FromArgb(151,175,180),Font=new Font("Segoe UI Semibold",7.5f),AutoSize=true,Location=new Point(22,69)});var profile=new Panel{Dock=DockStyle.Fill,BackColor=Ui.PrimaryLight};profile.Controls.Add(new Label{Text=fullName,ForeColor=Color.White,Font=new Font("Segoe UI Semibold",10.5f),AutoEllipsis=true,AutoSize=false,Size=new Size(190,25),Location=new Point(20,14)});profile.Controls.Add(new Label{Text=(role=="Admin"?"Admin":"Lecturer")+"  •  @"+username,ForeColor=Color.FromArgb(167,190,194),AutoSize=false,Size=new Size(190,22),Location=new Point(20,43)});var logout=new Button{Text="Sign out",Size=new Size(190,36),Location=new Point(20,78),FlatStyle=FlatStyle.Flat,BackColor=Color.Transparent,ForeColor=Color.White};logout.FlatAppearance.BorderColor=Color.FromArgb(75,105,110);logout.Click+=delegate{Close();};profile.Controls.Add(logout);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3,ColumnCount=1,BackColor=Ui.Primary};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,104));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,128));layout.Controls.Add(brand,0,0);layout.Controls.Add(menu,0,1);layout.Controls.Add(profile,0,2);navigation.Controls.Add(layout);var header=new Panel{Dock=DockStyle.Top,Height=64,BackColor=Color.White};var today=new Label{Text=DateTime.Today.ToString("dddd, dd MMMM yyyy"),AutoSize=true,ForeColor=Ui.Muted,Anchor=AnchorStyles.Top|AnchorStyles.Right,Location=new Point(760,22)};header.Controls.Add(pageTitle);header.Controls.Add(today);header.Resize+=delegate{today.Left=header.ClientSize.Width-today.Width-28;};Controls.Add(host);Controls.Add(header);Controls.Add(navigation);}
  void Add(string title,Control c){c.Dock=DockStyle.Fill;c.BackColor=Ui.Background;var b=new Button{Text="   "+title,TextAlign=ContentAlignment.MiddleLeft,Dock=DockStyle.Top,Height=48,FlatStyle=FlatStyle.Flat,BackColor=Ui.Primary,ForeColor=Color.FromArgb(188,208,211),Font=new Font("Segoe UI Semibold",9.5f),Cursor=Cursors.Hand,Padding=new Padding(10,0,0,0)};b.FlatAppearance.BorderSize=0;b.Click+=delegate{Show(title,c,b);};menu.Controls.Add(b);menu.Controls.SetChildIndex(b,0);buttons.Add(b);if(buttons.Count==1)Show(title,c,b);}
  void Show(string title,Control page,Button selected){host.Controls.Clear();host.Controls.Add(page);pageTitle.Text=title;foreach(var b in buttons){b.BackColor=b==selected?Ui.Accent:Ui.Primary;b.ForeColor=Color.White;}}
  void AddAdmin(){Add("Lecturers",new GridPage(db,"SELECT u.UserId,t.TeacherCode AS [Code],t.FullName AS [Name],t.Phone,u.Username,u.IsActive AS [Active] FROM Teachers t JOIN Users u ON u.UserId=t.UserId ORDER BY u.UserId","Users","UserId"));Add("University Classes",new GridPage(db,"SELECT r.RoomId,r.RoomName AS [Class],r.Department,r.ProgramName AS [Program],r.StudyLevel [Year],r.Semester,r.AcademicYear,t.FullName AS [HomeTeacher],r.IsActive AS [Active] FROM Rooms r LEFT JOIN Teachers t ON t.TeacherId=r.HomeRoomTeacherId ORDER BY r.RoomId","Rooms","RoomId"));Add("Courses",new CoursePage(db));Add("Lecturer Assignments",new GridPage(db,"SELECT ta.AssignmentId,t.FullName AS [Lecturer],r.RoomName AS [Class],s.SubjectCode+' - '+s.SubjectName AS [Course],ta.AcademicYear,ta.IsActive AS [Active] FROM TeacherAssignments ta JOIN Teachers t ON t.TeacherId=ta.TeacherId JOIN Rooms r ON r.RoomId=ta.RoomId JOIN Subjects s ON s.SubjectId=ta.SubjectId ORDER BY ta.AssignmentId","TeacherAssignments","AssignmentId"));Add("Timetable",new GridPage(db,"SELECT tt.TimetableId,r.RoomName AS [Class],s.SubjectCode+' - '+s.SubjectName AS [Course],t.FullName AS [Lecturer],CHOOSE(tt.DayOfWeek,'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday') [Day],tt.StartTime,tt.EndTime,tt.EffectiveFrom,tt.EffectiveTo,tt.IsActive AS [Active] FROM Timetables tt JOIN Rooms r ON r.RoomId=tt.RoomId JOIN Subjects s ON s.SubjectId=tt.SubjectId JOIN Teachers t ON t.TeacherId=tt.TeacherId ORDER BY tt.DayOfWeek,tt.StartTime,tt.TimetableId","Timetables","TimetableId"));Add("Students",new StudentPage(db,true,null));Add("Attendance Reports",new ReportPage(db,null));}
  void AddTeacher(){Add("Students",new StudentPage(db,false,teacherId));Add("Take Attendance",new AttendancePage(db,teacherId.Value));Add("Attendance History",new HistoryPage(db,teacherId));Add("Monthly Reports",new ReportPage(db,teacherId,false));if(db.Query("SELECT 1 FROM Rooms WHERE HomeRoomTeacherId=@t AND IsActive=1",new SqlParameter("@t",teacherId)).Rows.Count>0)Add("Home Room Overall",new ReportPage(db,teacherId,true));}
 }

 sealed class OverviewPage:UserControl
 {
  readonly Database db;readonly int? teacher;readonly Label students=Value(),classes=Value(),courses=Value(),attendance=Value();readonly string name,role;
  public OverviewPage(Database database,int? teacherId,string fullName,string userRole){db=database;teacher=teacherId;name=fullName;role=userRole;var welcome=new Label{Text="Welcome back, "+name,AutoSize=true,Font=new Font("Segoe UI Semibold",20),ForeColor=Ui.Text,Location=new Point(8,8)};var hint=new Label{Text=role=="Admin"?"Here is a concise overview of the university attendance system.":"Your classes, students and attendance tools are ready.",AutoSize=true,ForeColor=Ui.Muted,Location=new Point(10,48)};var cards=new TableLayoutPanel{Location=new Point(0,84),Height=132,Dock=DockStyle.Top,ColumnCount=4,Padding=new Padding(0,8,0,8)};for(var i=0;i<4;i++)cards.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,25));cards.Controls.Add(Card("Active students",students,"ST"),0,0);cards.Controls.Add(Card("Accessible classes",classes,"CL"),1,0);cards.Controls.Add(Card("Active courses",courses,"CO"),2,0);cards.Controls.Add(Card("Records this month",attendance,"AT"),3,0);var note=new Panel{Dock=DockStyle.Top,Height=150,BackColor=Color.White,Padding=new Padding(24)};note.Controls.Add(new Label{Text=role=="Admin"?"Quick start\n\nUse the navigation to manage lecturers, classes, courses and assignments. Attendance reports keep the same role-aware access rules.":"Quick start\n\nChoose Take Attendance, select an assigned class and course, confirm the date, then mark each student.",Dock=DockStyle.Fill,ForeColor=Ui.Text});Controls.Add(note);Controls.Add(cards);Controls.Add(hint);Controls.Add(welcome);Load+=delegate{LoadValues();};}
  static Label Value(){return new Label{Text="—",AutoSize=true,Font=new Font("Segoe UI Semibold",24),ForeColor=Ui.Text};}static Panel Card(string title,Label value,string mark){var p=new Panel{Dock=DockStyle.Fill,BackColor=Color.White,Margin=new Padding(8)};p.Controls.Add(new Label{Text=mark,TextAlign=ContentAlignment.MiddleCenter,Size=new Size(38,38),Location=new Point(18,17),BackColor=Ui.AccentLight,ForeColor=Ui.Accent,Font=new Font("Segoe UI Semibold",9)});value.Location=new Point(66,15);p.Controls.Add(value);p.Controls.Add(new Label{Text=title,AutoSize=true,ForeColor=Ui.Muted,Location=new Point(68,61)});return p;}void LoadValues(){students.Text=Convert.ToString(db.Query("SELECT COUNT(*) Value FROM Students WHERE IsActive=1").Rows[0][0]);courses.Text=Convert.ToString(db.Query("SELECT COUNT(*) Value FROM Subjects WHERE IsActive=1").Rows[0][0]);attendance.Text=Convert.ToString(db.Query("SELECT COUNT(*) Value FROM Attendance WHERE AttendanceDate>=DateSerial(Year(Date()),Month(Date()),1)").Rows[0][0]);classes.Text=Convert.ToString(db.Query(teacher.HasValue?"SELECT COUNT(DISTINCT r.RoomId) FROM Rooms r LEFT JOIN TeacherAssignments a ON a.RoomId=r.RoomId AND a.TeacherId=@t WHERE r.HomeRoomTeacherId=@t OR a.AssignmentId IS NOT NULL":"SELECT COUNT(*) FROM Rooms WHERE IsActive=1",new SqlParameter("@t",teacher)).Rows[0][0]);}
 }

 class GridPage:UserControl
 {
  protected readonly Database Db;protected readonly DataGridView Grid=new DataGridView();protected readonly FlowLayoutPanel Bar=new FlowLayoutPanel();readonly string sql,table,key;readonly TextBox search=new TextBox{Width=190};readonly ComboBox classFilter=new ComboBox{Width=170,DropDownStyle=ComboBoxStyle.DropDownList};protected DataTable allRows;
  public GridPage(Database db,string query,string tableName,string keyName){Db=db;sql=query;table=tableName;key=keyName;Grid.Dock=DockStyle.Fill;Grid.ReadOnly=true;Grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;Grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;Bar.Dock=DockStyle.Top;Bar.Height=68;Bar.Padding=new Padding(8);if(table=="Timetables"){var classes=Db.Query("SELECT RoomName AS [Name] FROM Rooms ORDER BY RoomName");classFilter.Items.Add("All classes");foreach(DataRow row in classes.Rows)classFilter.Items.Add(Convert.ToString(row["Name"]));classFilter.SelectedIndex=0;classFilter.SelectedIndexChanged+=delegate{FilterRows();};Bar.Controls.Add(Ui.Label("Class"));Bar.Controls.Add(classFilter);}Bar.Controls.Add(Ui.Label("Search"));Bar.Controls.Add(search);search.TextChanged+=delegate{FilterRows();};if(table.Length>0){Bar.Controls.Add(Ui.Button("Add "+Entity,delegate{AdminDialogs.Add(Db,table);LoadRows();}));Bar.Controls.Add(Ui.Secondary("Edit "+Entity,delegate{if(Grid.CurrentRow==null)throw new InvalidOperationException("Select a row first.");AdminDialogs.Edit(Db,table,Convert.ToInt32(Grid.CurrentRow.Cells[key].Value));LoadRows();}));Bar.Controls.Add(Ui.Secondary("Activate / deactivate",Toggle));}Bar.Controls.Add(Ui.Secondary("Refresh",delegate{LoadRows();}));Controls.Add(Grid);Controls.Add(Bar);Load+=delegate{LoadRows();};}
  string Entity{get{if(table=="Users")return "lecturer";if(table=="Rooms")return "class";if(table=="TeacherAssignments")return "assignment";if(table=="Timetables")return "timetable session";return "record";}}
  protected virtual void LoadRows(){allRows=Db.Query(sql);FilterRows();if(Grid.Columns.Contains(key))Grid.Columns[key].Visible=false;}
  protected void FilterRows(){if(allRows==null)return;var filters=new System.Collections.Generic.List<string>();var q=search.Text.Trim().Replace("'","''").Replace("[","[[]");if(q.Length>0){var expressions=new System.Collections.Generic.List<string>();foreach(DataColumn column in allRows.Columns)expressions.Add("CONVERT(["+column.ColumnName+"], System.String) LIKE '%"+q+"%'");filters.Add("("+string.Join(" OR ",expressions.ToArray())+")");}if(table=="Timetables"&&classFilter.SelectedIndex>0)filters.Add("[Class] = '"+Convert.ToString(classFilter.SelectedItem).Replace("'","''")+"'");var view=new DataView(allRows);view.RowFilter=string.Join(" AND ",filters.ToArray());Grid.DataSource=view;}
  void Toggle(object sender,EventArgs e){if(Grid.CurrentRow==null||!Grid.Columns.Contains("Active"))return;var id=Convert.ToInt32(Grid.CurrentRow.Cells[key].Value);var active=Convert.ToBoolean(Grid.CurrentRow.Cells["Active"].Value);Db.Execute("UPDATE "+table+" SET IsActive=@a WHERE "+key+"=@id",new SqlParameter("@a",!active),new SqlParameter("@id",id));LoadRows();}
 }

 sealed class CoursePage:GridPage
 {
  readonly ComboBox year=new ComboBox();
  public CoursePage(Database db):base(db,"","",""){year.DropDownStyle=ComboBoxStyle.DropDownList;year.Width=130;year.Items.AddRange(new object[]{"All courses","First Year","Second Year","Third Year","Fourth Year","Fifth Year"});year.SelectedIndex=0;year.SelectedIndexChanged+=delegate{LoadRows();};var add=new Button{Text="Add course",Width=110};add.Click+=delegate{Edit(null);};var edit=new Button{Text="Edit course",Width=110};edit.Click+=delegate{if(Grid.CurrentRow!=null)Edit(Convert.ToInt32(Grid.CurrentRow.Cells["SubjectId"].Value));};Bar.Controls.Add(new Label{Text="Year",AutoSize=true,Margin=new Padding(8,9,3,0)});Bar.Controls.Add(year);Bar.Controls.Add(add);Bar.Controls.Add(edit);var toggle=new Button{Text="Activate / deactivate",Width=155};toggle.Click+=delegate{if(Grid.CurrentRow==null)return;var id=Convert.ToInt32(Grid.CurrentRow.Cells["SubjectId"].Value);var active=Convert.ToBoolean(Grid.CurrentRow.Cells["Active"].Value);Db.Execute("UPDATE Subjects SET IsActive=@a WHERE SubjectId=@id",new SqlParameter("@a",!active),new SqlParameter("@id",id));LoadRows();};Bar.Controls.Add(toggle);}
  protected override void LoadRows(){var filter=year.SelectedIndex<=0?"":" WHERE CourseYear=@y";allRows=Db.Query("SELECT SubjectId,SubjectCode Code,SubjectName AS [Course],CourseYear AS [Year],IsActive AS [Active] FROM Subjects"+filter+" ORDER BY SubjectId",new SqlParameter("@y",Math.Max(1,year.SelectedIndex)));FilterRows();if(Grid.Columns.Contains("SubjectId"))Grid.Columns["SubjectId"].Visible=false;}
  void Edit(int? id){DataRow old=null;if(id.HasValue){var t=Db.Query("SELECT SubjectCode,SubjectName,CourseYear,IsActive FROM Subjects WHERE SubjectId=@id",new SqlParameter("@id",id.Value));if(t.Rows.Count==1)old=t.Rows[0];}using(var d=new CourseDialog(old)){if(d.ShowDialog()!=DialogResult.OK)return;if(id.HasValue)Db.Execute("UPDATE Subjects SET SubjectCode=@c,SubjectName=@n,CourseYear=@y WHERE SubjectId=@id",new SqlParameter("@c",d.Code),new SqlParameter("@n",d.NameValue),new SqlParameter("@y",d.Year),new SqlParameter("@id",id.Value));else Db.Execute("INSERT Subjects(SubjectCode,SubjectName,CourseYear,IsActive) VALUES(@c,@n,@y,1)",new SqlParameter("@c",d.Code),new SqlParameter("@n",d.NameValue),new SqlParameter("@y",d.Year));LoadRows();}}
 }
 sealed class CourseDialog:Form
 {readonly TextBox code=new TextBox(),name=new TextBox();readonly ComboBox year=new ComboBox();public string Code{get{return code.Text.Trim();}}public string NameValue{get{return name.Text.Trim();}}public int Year{get{return year.SelectedIndex+1;}}public CourseDialog(DataRow r){Text=r==null?"Add course":"Edit course";Width=400;Height=300;StartPosition=FormStartPosition.CenterParent;year.DropDownStyle=ComboBoxStyle.DropDownList;year.Items.AddRange(new object[]{"First Year","Second Year","Third Year","Fourth Year","Fifth Year"});year.SelectedIndex=r==null?0:Convert.ToInt32(r["CourseYear"])-1;if(r!=null){code.Text=Convert.ToString(r["SubjectCode"]);name.Text=Convert.ToString(r["SubjectName"]);}var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(25)};Add(p,"Course code",code);Add(p,"Course name",name);Add(p,"Year",year);var b=new Button{Text="Save",Width=300};b.Click+=delegate{DialogResult=DialogResult.OK;};p.Controls.Add(b);Controls.Add(p);AcceptButton=b;}public static void Add(FlowLayoutPanel p,string caption,Control c){p.Controls.Add(new Label{Text=caption,AutoSize=true});c.Width=300;p.Controls.Add(c);}}

 sealed class StudentPage:UserControl
 {
  readonly Database db;readonly bool admin;readonly int? teacher;readonly ComboBox rooms=new ComboBox();readonly DataGridView grid=new DataGridView();readonly FlowLayoutPanel bar=new FlowLayoutPanel();readonly TextBox search=new TextBox{Width=180};readonly Button add,edit,toggle;DataTable students;
  public StudentPage(Database database,bool isAdmin,int? teacherId){db=database;admin=isAdmin;teacher=teacherId;rooms.DropDownStyle=ComboBoxStyle.DropDownList;rooms.DisplayMember="Name";rooms.ValueMember="Id";rooms.Width=220;grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;bar.Dock=DockStyle.Top;bar.Height=68;bar.Controls.Add(Ui.Label("Class"));bar.Controls.Add(rooms);bar.Controls.Add(Ui.Label("Search"));bar.Controls.Add(search);add=Ui.Button("Add student",delegate{Edit(null);});edit=Ui.Secondary("Edit selected",delegate{if(grid.CurrentRow!=null)Edit(Convert.ToInt32(grid.CurrentRow.Cells["StudentId"].Value));});toggle=Ui.Secondary("Activate / deactivate",delegate{Toggle();});bar.Controls.Add(add);bar.Controls.Add(edit);bar.Controls.Add(toggle);rooms.SelectedIndexChanged+=delegate{LoadStudents();};search.TextChanged+=delegate{Filter();};Controls.Add(grid);Controls.Add(bar);Load+=delegate{LoadRooms();};}
  void LoadRooms(){var sql=admin?"SELECT RoomId AS [Id],RoomName AS [Name] FROM Rooms WHERE IsActive=1 ORDER BY RoomName":"SELECT DISTINCT r.RoomId AS [Id],r.RoomName AS [Name] FROM Rooms r LEFT JOIN TeacherAssignments a ON a.RoomId=r.RoomId AND a.TeacherId=@t AND a.IsActive=1 WHERE r.HomeRoomTeacherId=@t OR a.AssignmentId IS NOT NULL ORDER BY r.RoomName";rooms.DataSource=db.Query(sql,new SqlParameter("@t",teacher));}
  void LoadStudents(){if(rooms.SelectedValue==null)return;students=db.Query("SELECT StudentId,StudentCode AS [Registration No],StudentName AS [Student Name],Gender,IsActive AS [Active] FROM Students WHERE RoomId=@r ORDER BY StudentId",new SqlParameter("@r",rooms.SelectedValue));Filter();var canManage=admin||db.Query("SELECT 1 FROM Rooms WHERE RoomId=@r AND HomeRoomTeacherId=@t",new SqlParameter("@r",rooms.SelectedValue),new SqlParameter("@t",teacher)).Rows.Count>0;add.Enabled=edit.Enabled=toggle.Enabled=canManage;if(grid.Columns.Contains("StudentId"))grid.Columns["StudentId"].Visible=false;}
  void Filter(){if(students==null)return;var q=search.Text.Trim().Replace("'","''");var view=new DataView(students);if(q.Length>0)view.RowFilter="CONVERT([Registration No],System.String) LIKE '%"+q+"%' OR CONVERT([Student Name],System.String) LIKE '%"+q+"%' OR Gender LIKE '%"+q+"%'";grid.DataSource=view;}
  void EnsureManage(){if(!admin&&db.Query("SELECT 1 FROM Rooms WHERE RoomId=@r AND HomeRoomTeacherId=@t",new SqlParameter("@r",rooms.SelectedValue),new SqlParameter("@t",teacher)).Rows.Count==0)throw new InvalidOperationException("Only this class's home-room lecturer can manage its students.");}
  void Edit(int? id){EnsureManage();DataRow old=null;if(id.HasValue){var t=db.Query("SELECT * FROM Students WHERE StudentId=@id",new SqlParameter("@id",id.Value));if(t.Rows.Count>0)old=t.Rows[0];}using(var d=new StudentDialog(old)){if(d.ShowDialog()!=DialogResult.OK)return;if(id.HasValue)db.Execute("UPDATE Students SET StudentCode=@c,StudentName=@n,Gender=@g WHERE StudentId=@id",new SqlParameter("@c",d.Code),new SqlParameter("@n",d.NameValue),new SqlParameter("@g",d.Gender),new SqlParameter("@id",id.Value));else db.Execute("INSERT Students(StudentCode,StudentName,Gender,RoomId,AcademicYear,IsActive) SELECT @c,@n,@g,RoomId,AcademicYear,1 FROM Rooms WHERE RoomId=@r",new SqlParameter("@c",d.Code),new SqlParameter("@n",d.NameValue),new SqlParameter("@g",d.Gender),new SqlParameter("@r",rooms.SelectedValue));LoadStudents();}}
  void Toggle(){EnsureManage();if(grid.CurrentRow==null)return;var id=Convert.ToInt32(grid.CurrentRow.Cells["StudentId"].Value);var active=Convert.ToBoolean(grid.CurrentRow.Cells["Active"].Value);db.Execute("UPDATE Students SET IsActive=@a WHERE StudentId=@id AND RoomId=@r",new SqlParameter("@a",!active),new SqlParameter("@id",id),new SqlParameter("@r",rooms.SelectedValue));LoadStudents();}
 }
 sealed class StudentDialog:Form
 {readonly TextBox code=new TextBox(),name=new TextBox();readonly ComboBox gender=new ComboBox();public string Code{get{return code.Text.Trim();}}public string NameValue{get{return name.Text.Trim();}}public string Gender{get{return Convert.ToString(gender.SelectedItem);}}public StudentDialog(DataRow r){Text=r==null?"Add student":"Edit student";Width=400;Height=300;StartPosition=FormStartPosition.CenterParent;gender.DropDownStyle=ComboBoxStyle.DropDownList;gender.Items.AddRange(new object[]{"Male","Female","Other"});gender.SelectedIndex=0;if(r!=null){code.Text=Convert.ToString(r["StudentCode"]);name.Text=Convert.ToString(r["StudentName"]);var i=gender.FindStringExact(Convert.ToString(r["Gender"]));gender.SelectedIndex=i<0?2:i;}var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(25)};CourseDialog.Add(p,"Registration number",code);CourseDialog.Add(p,"Student name",name);CourseDialog.Add(p,"Gender",gender);var b=new Button{Text="Save",Width=300};b.Click+=delegate{DialogResult=DialogResult.OK;};p.Controls.Add(b);Controls.Add(p);AcceptButton=b;}}

 sealed class HistoryPage:UserControl
 {readonly Database db;readonly int? teacher;readonly DataGridView grid=new DataGridView();readonly DateTimePicker from=new DateTimePicker(),to=new DateTimePicker();public HistoryPage(Database database,int? teacherId){db=database;teacher=teacherId;grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;from.Value=DateTime.Today.AddMonths(-2);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=52};bar.Controls.Add(new Label{Text="From",AutoSize=true,Margin=new Padding(8,10,3,0)});bar.Controls.Add(from);bar.Controls.Add(new Label{Text="To",AutoSize=true,Margin=new Padding(8,10,3,0)});bar.Controls.Add(to);var view=new Button{Text="View history"};view.Click+=delegate{LoadRows();};var export=new Button{Text="Export all to Excel"};export.Click+=delegate{ExcelExporter.ExportGrid(grid,"Attendance History");};bar.Controls.Add(view);bar.Controls.Add(export);Controls.Add(grid);Controls.Add(bar);Load+=delegate{LoadRows();};}void LoadRows(){var permission=teacher.HasValue?" AND (a.TeacherId=@t OR EXISTS(SELECT 1 FROM Rooms r WHERE r.RoomId=a.RoomId AND r.HomeRoomTeacherId=@t))":"";grid.DataSource=db.Query("SELECT a.AttendanceDate AS [Date],st.StudentCode AS [Registration No],st.StudentName AS [Student Name],r.RoomName AS [Class],s.SubjectCode Course,a.Status AS Status,a.Remark,te.FullName AS [Recorded By] FROM Attendance a JOIN Students st ON st.StudentId=a.StudentId JOIN Rooms r ON r.RoomId=a.RoomId JOIN Subjects s ON s.SubjectId=a.SubjectId JOIN Teachers te ON te.TeacherId=a.TeacherId WHERE a.AttendanceDate BETWEEN @f AND @to"+permission+" ORDER BY a.AttendanceId",new SqlParameter("@f",from.Value.Date),new SqlParameter("@to",to.Value.Date),new SqlParameter("@t",teacher));}}
 sealed class ReportPage:UserControl
 {
  readonly Database db;readonly int? teacher;readonly bool homeOnly;readonly ComboBox rooms=new ComboBox(),subjects=new ComboBox(),month=new ComboBox(),year=new ComboBox();readonly DataGridView grid=new DataGridView();
  public ReportPage(Database database,int? teacherId,bool homeRoomOnly=false)
  {
   db=database;teacher=teacherId;homeOnly=homeRoomOnly;rooms.DisplayMember="Name";rooms.ValueMember="Id";rooms.Width=220;subjects.DisplayMember="Name";subjects.ValueMember="Id";subjects.Width=220;
   for(var i=1;i<=12;i++)month.Items.Add(new DateTime(2000,i,1).ToString("MMMM"));month.SelectedIndex=DateTime.Today.Month-1;for(var y=DateTime.Today.Year+1;y>=DateTime.Today.Year-5;y--)year.Items.Add(y);year.SelectedItem=DateTime.Today.Year;
   grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;
   var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=68,Padding=new Padding(8)};bar.Controls.Add(Ui.Label(homeOnly?"My home room":"Class"));bar.Controls.Add(rooms);
   if(teacher.HasValue&&!homeOnly){bar.Controls.Add(Ui.Label("Course"));bar.Controls.Add(subjects);rooms.SelectedValueChanged+=delegate{LoadSubjects();};}
   bar.Controls.Add(Ui.Label("Reporting month"));bar.Controls.Add(month);bar.Controls.Add(Ui.Label("Year"));bar.Controls.Add(year);bar.Controls.Add(Ui.Button("Generate report",delegate{LoadRows();}));bar.Controls.Add(Ui.Secondary("Export all to Excel",delegate{ExcelExporter.ExportGrid(grid,homeOnly?"Home Room Overall":"Monthly Attendance");}));
   Controls.Add(grid);Controls.Add(bar);Load+=delegate{LoadRooms();};
  }
  void LoadRooms()
  {
   var sql=teacher.HasValue?(homeOnly?"SELECT r.RoomId AS [Id],r.RoomName AS [Name] FROM Rooms r WHERE r.HomeRoomTeacherId=@t AND r.IsActive=1 ORDER BY r.RoomId":"SELECT DISTINCT r.RoomId AS [Id],r.RoomName AS [Name] FROM Rooms r LEFT JOIN TeacherAssignments a ON a.RoomId=r.RoomId AND a.TeacherId=@t AND a.IsActive=1 WHERE r.IsActive=1 AND (r.HomeRoomTeacherId=@t OR a.AssignmentId IS NOT NULL) ORDER BY r.RoomId"):"SELECT RoomId AS [Id],RoomName AS [Name] FROM Rooms WHERE IsActive=1 ORDER BY RoomId";
   rooms.DataSource=db.Query(sql,new SqlParameter("@t",teacher));if(teacher.HasValue&&!homeOnly)LoadSubjects();
  }
  void LoadSubjects()
  {
   if(!teacher.HasValue||homeOnly||rooms.SelectedValue==null){subjects.DataSource=null;return;}
   var isHome=db.Query("SELECT 1 FROM Rooms WHERE RoomId=@r AND HomeRoomTeacherId=@t AND IsActive=1",new SqlParameter("@r",rooms.SelectedValue),new SqlParameter("@t",teacher)).Rows.Count>0;
   var sql=isHome?"SELECT DISTINCT s.SubjectId AS [Id],s.SubjectCode+' - '+s.SubjectName AS [Name] FROM Subjects s JOIN TeacherAssignments a ON a.SubjectId=s.SubjectId WHERE a.RoomId=@r AND a.IsActive=1 AND s.IsActive=1 ORDER BY s.SubjectId":"SELECT DISTINCT s.SubjectId AS [Id],s.SubjectCode+' - '+s.SubjectName AS [Name] FROM Subjects s JOIN TeacherAssignments a ON a.SubjectId=s.SubjectId WHERE a.RoomId=@r AND a.TeacherId=@t AND a.IsActive=1 AND s.IsActive=1 ORDER BY s.SubjectId";
   subjects.DataSource=db.Query(sql,new SqlParameter("@r",rooms.SelectedValue),new SqlParameter("@t",teacher));
  }
  void LoadRows()
  {
   if(rooms.SelectedValue==null)return;
   if(homeOnly)
   {
    if(db.Query("SELECT 1 FROM Rooms WHERE RoomId=@r AND HomeRoomTeacherId=@t",new SqlParameter("@r",rooms.SelectedValue),new SqlParameter("@t",teacher)).Rows.Count==0)throw new UnauthorizedAccessException("Only this class's home-room lecturer can view the overall report.");
    db.Execute("EXEC RecalculateMonthlyAttendance @RoomId,@Month,@Year",new SqlParameter("@RoomId",rooms.SelectedValue),new SqlParameter("@Month",month.SelectedIndex+1),new SqlParameter("@Year",year.SelectedItem));
    grid.DataSource=db.Query("SELECT st.StudentCode AS [Registration No],st.StudentName AS [Student Name],m.TotalSessions AS [Total Sessions],m.PresentCount AS [Present],m.AbsentCount AS [Absent],m.AttendancePercentage AS [Attendance %],m.Remark FROM MonthlyAttendanceSummary m JOIN Students st ON st.StudentId=m.StudentId WHERE m.RoomId=@r AND m.Month=@m AND m.Year=@y ORDER BY m.SummaryId",new SqlParameter("@r",rooms.SelectedValue),new SqlParameter("@m",month.SelectedIndex+1),new SqlParameter("@y",year.SelectedItem));return;
   }
   if(teacher.HasValue)
   {
    if(subjects.SelectedValue==null){MessageBox.Show("No assigned course is available for this class.","Monthly Reports",MessageBoxButtons.OK,MessageBoxIcon.Information);grid.DataSource=null;return;}
    var allowed=db.Query("SELECT 1 FROM Rooms r WHERE r.RoomId=@r AND r.HomeRoomTeacherId=@t UNION ALL SELECT 1 FROM TeacherAssignments a WHERE a.RoomId=@r AND a.SubjectId=@s AND a.TeacherId=@t AND a.IsActive=1",new SqlParameter("@r",rooms.SelectedValue),new SqlParameter("@s",subjects.SelectedValue),new SqlParameter("@t",teacher));
    if(allowed.Rows.Count==0)throw new UnauthorizedAccessException("You can view only courses assigned to you, unless you are this class's home-room lecturer.");
    var sql=";WITH Weighted AS (SELECT st.StudentId,st.StudentCode,st.StudentName,a.Status,CASE WHEN a.AttendanceId IS NULL THEN 0 WHEN a.SessionId IS NULL THEN 1 ELSE CAST(CEILING(DATEDIFF(minute,tt.StartTime,tt.EndTime)/60.0) AS int) END SessionHours FROM Students st LEFT JOIN Attendance a ON a.StudentId=st.StudentId AND a.RoomId=@r AND a.SubjectId=@s AND MONTH(a.AttendanceDate)=@m AND YEAR(a.AttendanceDate)=@y LEFT JOIN ClassSessions cs ON cs.SessionId=a.SessionId AND cs.SessionStatus='Held' LEFT JOIN Timetables tt ON tt.TimetableId=cs.TimetableId WHERE st.RoomId=@r AND st.IsActive=1) SELECT w.StudentCode AS [Registration No],w.StudentName AS [Student Name],s.SubjectCode+' - '+s.SubjectName AS [Course],CAST(SUM(w.SessionHours) AS int) [Total Sessions],CAST(SUM(CASE WHEN w.Status='Present' THEN w.SessionHours ELSE 0 END) AS int) Present,CAST(SUM(CASE WHEN w.Status='Absent' THEN w.SessionHours ELSE 0 END) AS int) Absent,CAST(CASE WHEN SUM(w.SessionHours)=0 THEN 0 ELSE 100.0*SUM(CASE WHEN w.Status='Present' THEN w.SessionHours ELSE 0 END)/SUM(w.SessionHours) END AS decimal(5,2)) [Attendance %],CASE WHEN SUM(w.SessionHours)=0 THEN 'No attendance data' WHEN 100.0*SUM(CASE WHEN w.Status='Present' THEN w.SessionHours ELSE 0 END)/SUM(w.SessionHours)<75 THEN 'Attendance below 75%' ELSE 'Satisfactory' END Remark FROM Weighted w CROSS JOIN Subjects s WHERE s.SubjectId=@s GROUP BY w.StudentId,w.StudentCode,w.StudentName,s.SubjectCode,s.SubjectName ORDER BY w.StudentId";
    grid.DataSource=db.Query(sql,new SqlParameter("@r",rooms.SelectedValue),new SqlParameter("@s",subjects.SelectedValue),new SqlParameter("@m",month.SelectedIndex+1),new SqlParameter("@y",year.SelectedItem));return;
   }
   db.Execute("EXEC RecalculateMonthlyAttendance @RoomId,@Month,@Year",new SqlParameter("@RoomId",rooms.SelectedValue),new SqlParameter("@Month",month.SelectedIndex+1),new SqlParameter("@Year",year.SelectedItem));
   grid.DataSource=db.Query("SELECT st.StudentCode AS [Registration No],st.StudentName AS [Student Name],m.TotalSessions AS [Total Sessions],m.PresentCount AS [Present],m.AbsentCount AS [Absent],m.AttendancePercentage AS [Attendance %],m.Remark FROM MonthlyAttendanceSummary m JOIN Students st ON st.StudentId=m.StudentId WHERE m.RoomId=@r AND m.Month=@m AND m.Year=@y ORDER BY m.SummaryId",new SqlParameter("@r",rooms.SelectedValue),new SqlParameter("@m",month.SelectedIndex+1),new SqlParameter("@y",year.SelectedItem));
  }
 }
 sealed class AttendancePage:UserControl
 {readonly Database db;readonly int teacher;readonly DateTimePicker date=new DateTimePicker{Width=145,Format=DateTimePickerFormat.Custom,CustomFormat="dd MMM yyyy"};readonly DataGridView sessions=new DataGridView();public AttendancePage(Database database,int teacherId){db=database;teacher=teacherId;sessions.Dock=DockStyle.Fill;sessions.ReadOnly=true;sessions.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;sessions.SelectionMode=DataGridViewSelectionMode.FullRowSelect;var header=new Panel{Dock=DockStyle.Top,Height=66,BackColor=Ui.PrimaryLight};header.Controls.Add(new Label{Text="MY ASSIGNED SESSIONS",Dock=DockStyle.Top,Height=32,Padding=new Padding(20,8,0,0),ForeColor=Color.White,Font=new Font("Segoe UI Semibold",12.5f)});header.Controls.Add(new Label{Text="Choose one of your scheduled classes below to take attendance",Dock=DockStyle.Bottom,Height=30,Padding=new Padding(20,0,0,8),ForeColor=Color.FromArgb(180,205,208)});var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=68,Padding=new Padding(8),BackColor=Color.White};bar.Controls.Add(Ui.Label("Date"));bar.Controls.Add(date);bar.Controls.Add(Ui.Button("Load sessions",delegate{LoadRows();}));bar.Controls.Add(Ui.Button("Take attendance",delegate{Open();}));Controls.Add(sessions);Controls.Add(bar);Controls.Add(header);date.ValueChanged+=delegate{LoadRows();};Load+=delegate{LoadRows();};}void LoadRows(){var day=date.Value.DayOfWeek==DayOfWeek.Sunday?7:(int)date.Value.DayOfWeek;db.Execute("INSERT ClassSessions(TimetableId,RoomId,SubjectId,TeacherId,SessionDate) SELECT tt.TimetableId,tt.RoomId,tt.SubjectId,tt.TeacherId,@date FROM Timetables tt WHERE tt.TeacherId=@t AND tt.DayOfWeek=@d AND @date BETWEEN tt.EffectiveFrom AND tt.EffectiveTo AND tt.IsActive=1 AND NOT EXISTS(SELECT 1 FROM ClassSessions cs WHERE cs.TimetableId=tt.TimetableId AND cs.SessionDate=@date)",new SqlParameter("@date",date.Value.Date),new SqlParameter("@t",teacher),new SqlParameter("@d",day));sessions.DataSource=db.Query("SELECT cs.SessionId,r.RoomId,s.SubjectId,r.RoomName AS [Class],s.SubjectCode+' - '+s.SubjectName AS [Course],tt.StartTime,tt.EndTime,cs.SessionStatus AS [Status] FROM ClassSessions cs JOIN Timetables tt ON tt.TimetableId=cs.TimetableId JOIN Rooms r ON r.RoomId=cs.RoomId JOIN Subjects s ON s.SubjectId=cs.SubjectId WHERE cs.TeacherId=@t AND cs.SessionDate=@date AND tt.IsActive=1 ORDER BY cs.SessionDate,tt.StartTime,cs.SessionId",new SqlParameter("@t",teacher),new SqlParameter("@date",date.Value.Date));foreach(var n in new[]{"SessionId","RoomId","SubjectId"})if(sessions.Columns.Contains(n))sessions.Columns[n].Visible=false;}void Open(){if(sessions.CurrentRow==null){MessageBox.Show("Choose a scheduled session first.");return;}try{using(var d=new AttendanceDialog(db,teacher,Convert.ToInt32(sessions.CurrentRow.Cells["SessionId"].Value),Convert.ToInt32(sessions.CurrentRow.Cells["RoomId"].Value),Convert.ToInt32(sessions.CurrentRow.Cells["SubjectId"].Value),date.Value.Date,Convert.ToString(sessions.CurrentRow.Cells["Status"].Value))){d.ShowDialog();LoadRows();}}catch(Exception ex){MessageBox.Show("Unable to open attendance.\r\n\r\n"+ex.Message,"Take Attendance",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}}
 sealed class AttendanceDialog:Form
 {readonly Database db;readonly int teacher,session,room,subject;readonly DateTime date;readonly DataGridView grid=new DataGridView();readonly string initialStatus;public AttendanceDialog(Database database,int teacherId,int sessionId,int roomId,int subjectId,DateTime sessionDate,string statusText){db=database;teacher=teacherId;session=sessionId;room=roomId;subject=subjectId;date=sessionDate;initialStatus=statusText;Text="Take Attendance";Width=900;Height=650;grid.Dock=DockStyle.Fill;grid.AllowUserToAddRows=false;var t=db.Query("SELECT st.StudentId,st.StudentCode AS [Registration No],st.StudentName AS [Student Name],Nz(a.Status,'Present') AS Status,a.Remark FROM Students st LEFT JOIN Attendance a ON a.SessionId=@session AND a.StudentId=st.StudentId WHERE st.RoomId=@r AND st.IsActive=1 ORDER BY st.StudentId",new SqlParameter("@session",session),new SqlParameter("@r",room));t.Columns["Status"].ReadOnly=false;t.Columns["Remark"].ReadOnly=false;grid.AutoGenerateColumns=false;grid.ReadOnly=false;grid.Columns.Add(new DataGridViewTextBoxColumn{Name="StudentId",DataPropertyName="StudentId",Visible=false,ReadOnly=true});grid.Columns.Add(new DataGridViewTextBoxColumn{Name="Registration No",HeaderText="Registration No.",DataPropertyName="Registration No",ReadOnly=true,FillWeight=25});grid.Columns.Add(new DataGridViewTextBoxColumn{Name="Student Name",HeaderText="Student Name",DataPropertyName="Student Name",ReadOnly=true,FillWeight=38});var status=new DataGridViewComboBoxColumn{HeaderText="Attendance",DataPropertyName="Status",Name="StatusChoice",FlatStyle=FlatStyle.Flat,FillWeight=22};status.Items.AddRange("Present","Absent");grid.Columns.Add(status);grid.Columns.Add(new DataGridViewTextBoxColumn{Name="Remark",HeaderText="Remark",DataPropertyName="Remark",FillWeight=30});grid.DataSource=t;var actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=68,Padding=new Padding(8),BackColor=Color.White};actions.Controls.Add(Ui.Button("All present",delegate{SetAll("Present");}));actions.Controls.Add(Ui.Button("All absent",delegate{SetAll("Absent");}));actions.Controls.Add(Ui.Button("Save attendance",delegate{Save();}));actions.Controls.Add(Ui.Secondary("Cancel session",delegate{CancelSession();}));Controls.Add(grid);Controls.Add(actions);Ui.Grid(grid);grid.ReadOnly=false;grid.EditMode=DataGridViewEditMode.EditOnEnter;grid.Columns["StudentId"].ReadOnly=true;grid.Columns["Registration No"].ReadOnly=true;grid.Columns["Student Name"].ReadOnly=true;grid.Columns["StatusChoice"].ReadOnly=false;grid.Columns["Remark"].ReadOnly=false;grid.CurrentCellDirtyStateChanged+=delegate{if(grid.IsCurrentCellDirty)grid.CommitEdit(DataGridViewDataErrorContexts.Commit);};grid.DataError+=delegate(object sender,DataGridViewDataErrorEventArgs e){e.ThrowException=false;};if(initialStatus=="Cancelled")grid.Enabled=false;Font=new Font("Segoe UI",10);BackColor=Ui.Background;}void SetAll(string value){foreach(DataGridViewRow row in grid.Rows)row.Cells["StatusChoice"].Value=value;grid.Refresh();}void Save(){if(initialStatus=="Cancelled")throw new InvalidOperationException("Attendance cannot be recorded for a cancelled session.");foreach(DataGridViewRow row in grid.Rows){db.Execute("MERGE Attendance x USING(SELECT @session SessionId,@student StudentId) q ON x.SessionId=q.SessionId AND x.StudentId=q.StudentId WHEN MATCHED THEN UPDATE SET Status=@status,Remark=@remark,UpdatedAt=SYSUTCDATETIME(),UpdatedBy=@t WHEN NOT MATCHED THEN INSERT(SessionId,StudentId,RoomId,SubjectId,TeacherId,AttendanceDate,Status,Remark,UpdatedBy) VALUES(@session,@student,@r,@s,@t,@d,@status,@remark,@t);",new SqlParameter("@session",session),new SqlParameter("@student",row.Cells["StudentId"].Value),new SqlParameter("@status",row.Cells["StatusChoice"].Value),new SqlParameter("@remark",row.Cells["Remark"].Value??DBNull.Value),new SqlParameter("@r",room),new SqlParameter("@s",subject),new SqlParameter("@t",teacher),new SqlParameter("@d",date));}db.Execute("UPDATE ClassSessions SET SessionStatus='Held',UpdatedAt=SYSUTCDATETIME() WHERE SessionId=@id",new SqlParameter("@id",session));MessageBox.Show("Attendance saved successfully.","Saved",MessageBoxButtons.OK,MessageBoxIcon.Information);Close();}void CancelSession(){if(MessageBox.Show("Cancel this class session?","Confirm cancellation",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;var changed=db.Execute("UPDATE ClassSessions SET SessionStatus='Cancelled',UpdatedAt=SYSUTCDATETIME() WHERE SessionId=@id AND NOT EXISTS(SELECT 1 FROM Attendance WHERE SessionId=@id)",new SqlParameter("@id",session));if(changed==0)throw new InvalidOperationException("A session with attendance records cannot be cancelled.");Close();}}

 static class ExcelExporter
 {public static void ExportGrid(DataGridView grid,string sheet){if(grid.Rows.Count==0){MessageBox.Show("There is no report data to export.");return;}using(var dialog=new SaveFileDialog{Filter="Excel 2003 XML (*.xml)|*.xml",FileName=sheet.Replace(' ','_')+".xml"}){if(dialog.ShowDialog()!=DialogResult.OK)return;var settings=new XmlWriterSettings{Indent=true,Encoding=new UTF8Encoding(false)};using(var w=XmlWriter.Create(dialog.FileName,settings)){w.WriteStartDocument();w.WriteProcessingInstruction("mso-application","progid=\"Excel.Sheet\"");w.WriteStartElement("Workbook","urn:schemas-microsoft-com:office:spreadsheet");w.WriteAttributeString("xmlns","ss",null,"urn:schemas-microsoft-com:office:spreadsheet");w.WriteStartElement("Worksheet");w.WriteAttributeString("ss","Name",null,sheet.Length>31?sheet.Substring(0,31):sheet);w.WriteStartElement("Table");w.WriteStartElement("Row");foreach(DataGridViewColumn c in grid.Columns)if(c.Visible)Cell(w,c.HeaderText);w.WriteEndElement();foreach(DataGridViewRow r in grid.Rows){if(r.IsNewRow)continue;w.WriteStartElement("Row");foreach(DataGridViewColumn c in grid.Columns)if(c.Visible)Cell(w,Convert.ToString(r.Cells[c.Index].Value));w.WriteEndElement();}w.WriteEndElement();w.WriteEndElement();w.WriteEndElement();w.WriteEndDocument();}MessageBox.Show("All report rows were exported for Excel.");}}static void Cell(XmlWriter w,string value){w.WriteStartElement("Cell");w.WriteStartElement("Data");w.WriteAttributeString("ss","Type",null,"String");w.WriteString(value??"");w.WriteEndElement();w.WriteEndElement();}}
